#!/usr/bin/env bash
# name: regen-conflicts.sh
# purpose: unstick a PR whose only conflict with its base is generated files - merge the base, regenerate, push
# inputs: --repo DIR (a clone of the PR's repository), --pr N or --all; env PR_FLOW_REGEN_PATHS, PR_FLOW_REGEN_CMD, GH_REPO
# outputs: one line per PR: regenerated, clean, real-conflict or skipped, with the paths
# writes-to: a temporary worktree under PR_FLOW_STATE/regen (removed on exit); a merge commit pushed to the PR branch
# cleanup: the worktree is removed by this script; make pr-flow-clean removes PR_FLOW_STATE
#
#   regen-conflicts.sh --repo DIR (--pr N | --all) [--dry-run]
#
# BREADCRUMB 2026-10-16 - BR-20261016-merge-port, order ORD-0545. What broke: every dotfiles ticket PR rewrites work-orders/INDEX.md and
#   the epic README.md (work-order.sh done), so each merge left the next ticket PR CONFLICTING, and GitHub runs no pull_request workflow
#   for a PR it cannot merge: no CI, no green, no merge (dotfiles 159, 161, 162, 180, 187 on 2026-10-16). Why this fix: those files are
#   a pure function of the ticket files, so the conflict is resolved by taking either side and running the generator. Why a local
#   script and not the GitHub Action the order named: a push made with GITHUB_TOKEN starts no workflow, so the regenerated head would
#   never get CI; this runs with the seat's own gh login, whose push does. Rejected: rebasing (rewrites a branch a worker may hold).
#   Cost: a PR conflicting on any path outside PR_FLOW_REGEN_PATHS is left alone and reported real-conflict for its worker (409).
set -uo pipefail
REPO=""; PR=""; ALL=0; DRY=0
die() { local c=$1; shift; echo "regen: $*" >&2; exit "$c"; }
while [ $# -gt 0 ]; do case $1 in
  --repo) REPO=$(cd "${2:?}" && pwd) || die 2 "no such --repo"; shift 2;; --pr) PR=${2:?}; shift 2;; --all) ALL=1; shift;;
  --dry-run) DRY=1; shift;; *) die 2 "unknown argument $1";; esac; done
[ -n "$REPO" ] || die 2 "--repo is required"
{ [ -n "$PR" ] && [ "$ALL" = 0 ]; } || { [ -z "$PR" ] && [ "$ALL" = 1 ]; } || die 2 "give --pr N or --all"
read -r -a GLOBS <<<"${PR_FLOW_REGEN_PATHS:-work-orders/INDEX.md work-orders/*/README.md}"
CMD=${PR_FLOW_REGEN_CMD:-bash claude/skills/work-order/scripts/work-order.sh reindex}
STATE=${PR_FLOW_STATE:-$HOME/.local/state/zenith/pr-flow}; mkdir -p "$STATE/regen" || die 4 "cannot make $STATE/regen"
WT=""; cleanup() { [ -z "$WT" ] || { git -C "$REPO" worktree remove --force "$WT" >/dev/null 2>&1; rm -rf "$WT"; }; }; trap cleanup EXIT

# shellcheck disable=SC2053 # $g is a glob from config, matched as one on purpose
generated() { local f=$1 g; for g in "${GLOBS[@]}"; do [[ $f == $g ]] && return 0; done; return 1; }

one() { # one PR: prints its line, returns 0 regenerated or clean, 1 real conflict, 4 io
  local pr=$1 view branch base mergeable bad=() f files n
  for n in 1 2 3 4 5; do   # UNKNOWN is GitHub still computing after a base moved
    view=$(cd "$REPO" && gh pr view "$pr" --json headRefName,baseRefName,mergeable,state 2>/dev/null) || { echo "PR $pr io: gh pr view failed"; return 4; }
    mergeable=$(jq -r .mergeable <<<"$view"); [ "$mergeable" != UNKNOWN ] && break; sleep $((n * ${REGEN_BACKOFF:-3}))
  done
  branch=$(jq -r .headRefName <<<"$view"); base=$(jq -r .baseRefName <<<"$view")
  [ "$(jq -r .state <<<"$view")" = OPEN ] || { echo "PR $pr skipped: not open"; return 0; }
  [ "$mergeable" = CONFLICTING ] || { echo "PR $pr clean: mergeable $mergeable"; return 0; }
  git -C "$REPO" fetch -q origin "$branch" "$base" || { echo "PR $pr io: fetch failed"; return 4; }
  WT=$(mktemp -d "$STATE/regen/pr-$pr.XXXX"); rmdir "$WT"
  git -C "$REPO" worktree add -q --detach "$WT" "origin/$branch" || { echo "PR $pr io: worktree failed"; WT=""; return 4; }
  git -C "$WT" -c user.name=pr-flow -c user.email=pr-flow@example.invalid merge -q --no-edit "origin/$base" >/dev/null 2>&1
  mapfile -t files < <(git -C "$WT" diff --name-only --diff-filter=U)
  for f in "${files[@]}"; do generated "$f" || bad+=("$f"); done
  if [ "${#files[@]}" = 0 ] || [ "${#bad[@]}" -gt 0 ]; then
    git -C "$WT" merge --abort >/dev/null 2>&1; cleanup; WT=""
    echo "PR $pr real-conflict: ${bad[*]:-none listed by git}"; return 1
  fi
  for f in "${files[@]}"; do git -C "$WT" checkout -q --theirs -- "$f"; done
  (cd "$WT" && eval "$CMD") >/dev/null 2>&1 || { cleanup; WT=""; echo "PR $pr io: regen command failed: $CMD"; return 4; }
  git -C "$WT" add -A && git -C "$WT" -c user.name=pr-flow -c user.email=pr-flow@example.invalid commit -q --no-edit \
    -m "Merge $base into $branch; ${files[*]} regenerated by pr-flow regen-conflicts.sh" || { cleanup; WT=""; echo "PR $pr io: commit failed"; return 4; }
  if [ "$DRY" = 1 ]; then echo "PR $pr would-regenerate: ${files[*]}"; else
    git -C "$WT" push -q origin "HEAD:refs/heads/$branch" || { cleanup; WT=""; echo "PR $pr io: push failed"; return 4; }
    echo "PR $pr regenerated: ${files[*]}"; fi
  cleanup; WT=""; return 0
}

if [ "$ALL" = 0 ]; then one "$PR"; exit $?; fi
mapfile -t NUMS < <(cd "$REPO" && gh pr list --state open --limit 200 --json number,mergeable --jq '.[] | select(.mergeable == "CONFLICTING") | .number' 2>/dev/null)
rc=0; for p in "${NUMS[@]}"; do one "$p" || { r=$?; [ "$r" = 4 ] && rc=4; }; done; exit "$rc"
